import { test } from "node:test";
import assert from "node:assert/strict";
import { canShip } from "../src/deploy.ts";

test("allows deploys before 16:00 Berlin time on regular days", () => {
  // 2026-11-17 14:00 Berlin time (not a month-end freeze day)
  const now = new Date("2026-11-17T13:00:00Z"); // 14:00 Berlin (UTC+1)
  assert.equal(canShip(now), true);
});

test("refuses deploys after 16:00 Berlin time", () => {
  // 2026-11-17 16:00 Berlin time
  const now = new Date("2026-11-17T15:00:00Z"); // 16:00 Berlin (UTC+1)
  assert.equal(canShip(now), false);
});

test("refuses deploys late in the day", () => {
  // 2026-11-17 20:00 Berlin time
  const now = new Date("2026-11-17T19:00:00Z"); // 20:00 Berlin (UTC+1)
  assert.equal(canShip(now), false);
});

test("refuses deploys on the last working day of the month", () => {
  // 2026-11-30 is Monday, the last working day of November
  const now = new Date("2026-11-30T12:00:00Z"); // 13:00 Berlin (UTC+1), before 16:00
  assert.equal(canShip(now), false);
});

test("refuses deploys on the second-to-last working day of the month", () => {
  // 2026-11-27 is Friday, second-to-last working day (Nov 28-29 are weekend, Nov 30 is last working day)
  const now = new Date("2026-11-27T12:00:00Z"); // 13:00 Berlin (UTC+1), before 16:00
  assert.equal(canShip(now), false);
});

test("allows deploys on third-to-last working day of the month", () => {
  // 2026-11-26 is Thursday, third-to-last working day
  const now = new Date("2026-11-26T12:00:00Z"); // 13:00 Berlin (UTC+1), before 16:00
  assert.equal(canShip(now), true);
});

test("handles month ending on Friday correctly", () => {
  // 2026-10-30 is Friday and last day of October
  // Last working days are Oct 29 (Thu) and Oct 30 (Fri)
  const lastDay = new Date("2026-10-30T12:00:00Z"); // Friday, last working day
  assert.equal(canShip(lastDay), false);

  const secondToLast = new Date("2026-10-29T12:00:00Z"); // Thursday, second-to-last working day
  assert.equal(canShip(secondToLast), false);

  const thirdToLast = new Date("2026-10-28T12:00:00Z"); // Wednesday, OK to ship
  assert.equal(canShip(thirdToLast), true);
});

test("handles month ending on weekend correctly", () => {
  // 2026-08-31 is Monday, but it's preceded by Aug 29-30 (weekend)
  // Last working days are Aug 28 (Fri) and Aug 31 (Mon)
  const lastDay = new Date("2026-08-31T12:00:00Z"); // Monday, last working day
  assert.equal(canShip(lastDay), false);

  const secondToLast = new Date("2026-08-28T12:00:00Z"); // Friday, second-to-last working day
  assert.equal(canShip(secondToLast), false);

  const weekend = new Date("2026-08-30T12:00:00Z"); // Sunday, not a working day - should allow
  assert.equal(canShip(weekend), true);

  const thirdToLast = new Date("2026-08-27T12:00:00Z"); // Thursday, OK to ship
  assert.equal(canShip(thirdToLast), true);
});

test("combines both rules: refuses if either condition fails", () => {
  // Last working day AND after 16:00
  const now = new Date("2026-11-30T16:00:00Z"); // 17:00 Berlin, last working day
  assert.equal(canShip(now), false);
});

